parser.script:
// 观果：POST JSON 体里的中文必须转义成 \uXXXX，否则站方 500。
// clientInfo = md5(毫秒时间戳字符串的后 10 位)，每次请求现算。
function ggBody(raw) {
  // 形态归一：单条 meta 预取的处理器入参在旧引擎是打包数组 [响应体, 响应头]，
  // 新引擎逐参传递后首参即响应体。所有处理器都经 ggParse，在此一处归一。
  return (Array.isArray(raw) && raw.length > 0 && raw[0] && typeof raw[0] === 'object') ? raw[0] : raw;
}
function ggParse(raw) {
  raw = ggBody(raw);
  if (raw && typeof raw === 'object') return raw;
  if (typeof raw !== 'string' || !raw) return null;
  try { return JSON.parse(raw); } catch (e) { return null; }
}
function ggEscape(text) {
  return String(text == null ? '' : text).replace(/[\u0080-\uffff]/g, function (ch) {
    var hex = ch.charCodeAt(0).toString(16);
    while (hex.length < 4) hex = '0' + hex;
    return '\\u' + hex;
  });
}
function ggStrip(base) { return String(base || '').replace(/\/+$/, ''); }
function ggCommon() {
  return 'version_code=1500&version_name=1.5.0&device_name=Pixel%208%20Pro&device_type=phone&is_first_day=true&is_first_24h=true&app_launch_way=icon&default_homepage=homepage_interaction&device_owning_firm=Google&font_scale=default&os_type=1';
}
function ggViews(count) {
  count = Number(count) || 0;
  if (count <= 0) return '';
  if (count >= 10000) return (Math.round(count / 1000) / 10) + '万次播放';
  return count + '次播放';
}
function ggItems(json) {
  var out = [];
  var rows = (json && json.data) || [];
  for (var i = 0; i < rows.length; i++) {
    var node = rows[i];
    var id = node.oneId || node.one_id || node.id;
    if (!id) continue;
    out.push({
      id: String(id),
      title: node.title || node.name || '',
      cover: node.vertPoster || node.horzPoster || node.cover || '',
      description: node.description || node.desc || '',
      episodeCount: node.episodeCount || node.totalEpisodeCount || '',
      tags: node.shortPlayTag || [],
      views: ggViews(node.viewCount)
    });
  }
  return out;
}
function ggSearch(context, overrides) {
  var page = (context && Number(context.page)) || 1;
  if (page > 500) return [];
  var body = {
    audience: '\u5168\u90e8',
    order: '\u6700\u65b0',
    page: page,
    pageSize: 30,
    searchWord: (context && context.keyword) || '',
    subject: (context && context.category) || ''
  };
  if (overrides) {
    for (var key in overrides) { body[key] = overrides[key]; }
  }
  var pairs = [];
  for (var k in body) { pairs.push('"' + k + '":' + (typeof body[k] === 'number' ? body[k] : '"' + ggEscape(body[k]) + '"')); }
  var payload = '{' + pairs.join(',') + '}';
  return ggMeta(context, '/drama/home/search', payload);
}
function ggMeta(context, path, payload) {
  return context.crypto.md5(String(Date.now()).slice(-10)).then(function (ci) {
    return {
      __meta: true,
      __fetchUrl: ggStrip(context && context.baseUrl) + path + '?' + ggCommon() + '&clientInfo=' + ci,
      __fetchMethod: 'post',
      __fetchBody: payload,
      __fetchHeaders: { 'Content-Type': 'application/json; charset=utf-8' },
      __processor: 'ggPickRaw'
    };
  });
}
function ggPickRaw(raw) {
  var json = ggParse(raw);
  return ggItems(json);
}
function parseList(raw, context) { return ggSearch(context, null); }
function parseCategory(raw, context) {
  var c = (context && context.category) || '';
  // 频道维度（男频/女频）走 audience 字段；题材维度走 subject 字典。
  if (c === '男频' || c === '女频') return ggSearch(context, { audience: c, subject: '' });
  return ggSearch(context, null);
}
function parseSearch(raw, context) { return ggSearch(context, null); }
// 详情/选集：GET shortVideoDetail（站方 2026-11 故障恒空，脚本原样透传空产出）。
// 详情/选集/播放（v4）：App 详情端点 shortVideoDetail 2026-11 起对任意 id 恒返 data:null
// （站方数据故障，基准同期失效），改走站方 H5 现行链路：
//   GET /drama/play/h5/detail?deviceId=..&os_type=2&oneId=..[&playOrder=N]
// 不带 playOrder=剧集概要（title/description/episodeCount/subjectTags）；带 playOrder=
// 该集 h5PlayUrl+h5PlayKey：AES-256-CBC（密文 base64 前 16 字节为 IV，key 32 字节，
// PKCS7），明文 JSON {super,high,normal} 三档带时效签名 mp4 直链。
async function ggDeviceId(context) {
  var saved = '';
  try { saved = (await context.storage.get('gg_device')) || ''; } catch (e) {}
  if (saved) return saved;
  var d = 'device_nexhub_' + String(Date.now()) + '_' + String(Math.floor(Math.random() * 1000000));
  try { await context.storage.set('gg_device', d); } catch (e) {}
  return d;
}
async function ggH5Meta(context, playOrder, processor) {
  var dev = await ggDeviceId(context);
  var oneId = String((context && context.id) || '');
  var u = ggStrip(context && context.baseUrl) + '/drama/play/h5/detail?deviceId=' + encodeURIComponent(dev) + '&os_type=2&oneId=' + encodeURIComponent(oneId);
  if (Number(playOrder) > 0) u += '&playOrder=' + Number(playOrder);
  return { __meta: true, __fetchUrl: u, __fetchResponseType: 'json', __processor: processor };
}
function parseDetail(raw, context) { return ggH5Meta(context, 0, 'ggDetailRaw'); }
function ggDetailRaw(raw, context) {
  var json = ggParse(raw);
  if (!json) return { id: '' };
  var d = json.data || json || {};
  var cid = String((context && context.id) || '');
  return {
    id: String(d.oneId || cid),
    title: d.title || '',
    cover: d.vertPoster || '',
    description: d.description || '',
    tags: d.subjectTags || [],
    episodeCount: Number(d.episodeCount) || ''
  };
}
var GG_DEV = '';
async function parseEpisodes(raw, context) {
  GG_DEV = await ggDeviceId(context);
  return ggH5Meta(context, 0, 'ggPickEpisodes');
}
function ggH5EpisodeUrl(context, oneId, n) {
  return ggStrip(context && context.baseUrl) + '/drama/play/h5/detail?deviceId=' + encodeURIComponent(GG_DEV) + '&os_type=2&oneId=' + encodeURIComponent(String(oneId)) + '&playOrder=' + n + '#ep=' + n;
}
function ggPickEpisodes(raw, context) {
  var json = ggParse(raw);
  if (!json) return [];
  var d = json.data || json || {};
  var oneId = String(d.oneId || (context && context.id) || '');
  var total = Number(d.episodeCount) || 0;
  if (!oneId || total <= 0) return [];
  var out = [];
  for (var i = 1; i <= total; i++) {
    out.push({
      id: oneId + '_' + i,
      title: '第' + i + '集',
      number: i,
      url: ggH5EpisodeUrl(context, oneId, i)
    });
  }
  return out;
}
async function parseVideo(raw, context) {
  var url = (context && context.url) || '';
  var cut = url.indexOf('#ep=');
  var env = ggParse(raw);
  var d = env && (env.data || env);
  if (!d || !d.h5PlayUrl) {
    var target = cut >= 0 ? url.slice(0, cut) : url;
    if (target.indexOf('http') !== 0 && target.indexOf('/') === 0) target = ggStrip(context && context.baseUrl) + target;
    if (target.indexOf('http') === 0) {
      try { env = ggParse(await context.http.getJson(target)); } catch (e) { env = null; }
      d = env && (env.data || env);
    }
  }
  if (!d || !d.h5PlayUrl || !d.h5PlayKey) return '';
  try {
    var bin = atob(d.h5PlayUrl);
    var text = await context.crypto.aesCbc(d.h5PlayKey, btoa(bin.slice(16)), btoa(bin.slice(0, 16)), false, 'base64');
    var o = JSON.parse(text);
    return o.super || o.high || o.normal || '';
  } catch (e) { return '';
}
}
